select jsonb_build_object(
 'ledger',(select jsonb_build_object('version',version,'name',name,'statements',cardinality(statements),'source_md5',md5(replace(array_to_string(statements,E'\n'),chr(13),''))) from supabase_migrations.schema_migrations where name='20261021190916_collaboration_procedure_routines'),
 'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'auth_select',has_table_privilege('authenticated',c.oid,'SELECT'),'auth_insert',has_table_privilege('authenticated',c.oid,'INSERT'),'auth_update',has_table_privilege('authenticated',c.oid,'UPDATE'),'auth_delete',has_table_privilege('authenticated',c.oid,'DELETE'),'auth_truncate',has_table_privilege('authenticated',c.oid,'TRUNCATE'),'anon_select',has_table_privilege('anon',c.oid,'SELECT'))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('record_discussions','operating_procedures','operating_procedure_events','daily_routine_runs','daily_routine_completions')),
 'policies',(select jsonb_agg(jsonb_build_object('table',tablename,'command',cmd,'roles',roles,'qual',qual)) from pg_policies where schemaname='public' and tablename in ('record_discussions','operating_procedures','operating_procedure_events','daily_routine_runs','daily_routine_completions','customers') and cmd='SELECT'),
 'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'definer',p.prosecdef,'settings',p.proconfig,'body_md5',md5(btrim(replace(p.prosrc,chr(13),''))),'auth_exec',has_function_privilege('authenticated',p.oid,'EXECUTE'),'anon_exec',has_function_privilege('anon',p.oid,'EXECUTE'),'public_exec',exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee=0 and a.privilege_type='EXECUTE')) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname in ('customer_has_current_dealer_record','collaboration_can_read','collaboration_record_visible','operating_procedure_projection','daily_routine_projection','daily_routine_sources','collaboration_workflow_command','guard_quote_preparation_stage')),
 'quote_trigger',(select pg_get_triggerdef(oid) from pg_trigger where tgrelid='public.quotes'::regclass and tgname='quote_preparation_stage_guard'),
 'quote_columns',(select jsonb_object_agg(column_name,has_column_privilege('authenticated','public.quotes',column_name,'SELECT')) from information_schema.columns where table_schema='public' and table_name='quotes' and column_name in ('id','company_id','status','subtotal','grand_total')),
 'new_row_counts',jsonb_build_object('discussions',(select count(*) from public.record_discussions),'procedures',(select count(*) from public.operating_procedures),'events',(select count(*) from public.operating_procedure_events),'runs',(select count(*) from public.daily_routine_runs),'completions',(select count(*) from public.daily_routine_completions))
) as collaboration_upgrade;
